  1128  cdf_unpack_summary_info(const cdf_stream_t *sst, const cdf_header_t *h,
  1129      cdf_summary_info_header_t *ssi, cdf_property_info_t **info, size_t *count)
  1130  {
  1131          size_t maxcount;
  1132          const cdf_summary_info_header_t *si =
  1133              CAST(const cdf_summary_info_header_t *, sst->sst_tab);
  1134          const cdf_section_declaration_t *sd =
  1135              CAST(const cdf_section_declaration_t *, RCAST(const void *,
  1136              RCAST(const char *, sst->sst_tab)
  1137              + CDF_SECTION_DECLARATION_OFFSET));
  1138
  1139          if (cdf_check_stream_offset(sst, h, si, sizeof(*si), __LINE__) == -1 ||
  1140              cdf_check_stream_offset(sst, h, sd, sizeof(*sd), __LINE__) == -1)
  1141                  return -1;
  1142          ssi->si_byte_order = CDF_TOLE2(si->si_byte_order);
  1143          ssi->si_os_version = CDF_TOLE2(si->si_os_version);
  1144          ssi->si_os = CDF_TOLE2(si->si_os);
  1145          ssi->si_class = si->si_class;
  1146          cdf_swap_class(&ssi->si_class);
  1147          ssi->si_count = CDF_TOLE4(si->si_count);
  1148          *count = 0;
  1149          maxcount = 0;
  1150          *info = NULL;
  1151          if (cdf_read_property_info(sst, h, CDF_TOLE4(sd->sd_offset), info,
  1152              count, &maxcount) == -1)
  1153                  return -1;
  1154          return 0;
  1155  }
